<template><div class="structured"><template v-if="isObject"><div v-for="(value,key) in objectValue" :key="String(key)" class="field"><label>{{key}}</label><StructuredValueEditor :model-value="value" @update:model-value="updateKey(String(key),$event)"/><button title="删除字段" @click="removeKey(String(key))">×</button></div><button @click="addKey">添加字段</button></template><template v-else-if="Array.isArray(modelValue)"><div v-for="(value,index) in modelValue" :key="index" class="field"><label>#{{index+1}}</label><StructuredValueEditor :model-value="value" @update:model-value="updateIndex(index,$event)"/><button title="删除项目" @click="removeIndex(index)">×</button></div><button @click="addItem">添加项目</button></template><label v-else-if="typeof modelValue==='boolean'" class="boolean"><input type="checkbox" :checked="modelValue" @change="emit('update:modelValue',($event.target as HTMLInputElement).checked)"/>{{modelValue?'是':'否'}}</label><input v-else-if="typeof modelValue==='number'" type="number" :value="modelValue" @input="emit('update:modelValue',Number(($event.target as HTMLInputElement).value))"/><textarea v-else :value="String(modelValue??'')" rows="2" @input="emit('update:modelValue',($event.target as HTMLTextAreaElement).value)"/></div></template>
<script setup lang="ts">import{computed}from'vue';defineOptions({name:'StructuredValueEditor'});const props=defineProps<{modelValue:unknown}>(),emit=defineEmits<{ 'update:modelValue':[value:unknown]}>();const isObject=computed(()=>props.modelValue!==null&&typeof props.modelValue==='object'&&!Array.isArray(props.modelValue)),objectValue=computed(()=>props.modelValue as Record<string,unknown>);function updateKey(k:string,v:unknown){emit('update:modelValue',{...objectValue.value,[k]:v})}function removeKey(k:string){const next={...objectValue.value};delete next[k];emit('update:modelValue',next)}function addKey(){const key=prompt('新字段名');if(key&&!Object.prototype.hasOwnProperty.call(objectValue.value,key))updateKey(key,'')}function updateIndex(i:number,v:unknown){const next=[...(props.modelValue as unknown[])];next[i]=v;emit('update:modelValue',next)}function removeIndex(i:number){const next=[...(props.modelValue as unknown[])];next.splice(i,1);emit('update:modelValue',next)}function addItem(){emit('update:modelValue',[...(props.modelValue as unknown[]),''])}</script>
<style scoped>.structured{display:grid;gap:6px}.field{display:grid;grid-template-columns:minmax(70px,auto) minmax(0,1fr) auto;align-items:start;gap:6px;padding:6px;border-left:1px solid #504a3e}.field>label{color:#bcb3a2;overflow-wrap:anywhere}.structured input,.structured textarea{width:100%;padding:6px;color:#eee;background:#111;border:1px solid #555}.boolean{display:flex;gap:6px}.boolean input{width:auto}</style>
